#!/usr/bin/env python3
"""gen-annex29-columns.py — generate Go constants from Annex 29 column definitions CSV.

Usage:
  python3 scripts/gen-annex29-columns.py [--check]

  --check: compare generated output with existing file; exit 1 on mismatch.
"""
import sys
import os
import csv
import io

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CSV_FILE = os.path.join(ROOT, "docs", "SUPTO", "annex29_columns.csv")
OUT_FILE = os.path.join(ROOT, "fiscal-backend", "internal", "domain", "annex29_columns_gen.go")

HEADER = """\
// Code generated by scripts/gen-annex29-columns.py — DO NOT EDIT.
package domain

// Annex29Column constants from docs/SUPTO/annex29_columns.csv
const (
"""

FOOTER = ")\n"


def load_csv(path):
    rows = []
    if not os.path.exists(path):
        raise FileNotFoundError(f"CSV not found: {path}")
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(row)
    return rows


def to_go_name(s):
    parts = s.replace("-", " ").replace("_", " ").split()
    return "Annex29Col" + "".join(p.capitalize() for p in parts if p)


def generate(rows):
    buf = io.StringIO()
    buf.write(HEADER)
    for row in rows:
        name = row.get("name") or row.get("column") or row.get("id") or ""
        index = row.get("index") or row.get("col_index") or row.get("number") or ""
        if not name:
            continue
        go_name = to_go_name(name)
        comment = row.get("description") or row.get("label") or name
        buf.write(f'\t// {comment}\n')
        buf.write(f'\t{go_name} = {index!r}\n')
    buf.write(FOOTER)
    return buf.getvalue()


def main():
    check_mode = "--check" in sys.argv
    try:
        rows = load_csv(CSV_FILE)
    except FileNotFoundError as e:
        print(f"GEN-ENV: {e}", file=sys.stderr)
        sys.exit(3)

    output = generate(rows)

    if check_mode:
        if not os.path.exists(OUT_FILE):
            print(f"GEN-CHECK-001: {OUT_FILE} does not exist (run without --check to generate)", file=sys.stderr)
            sys.exit(1)
        with open(OUT_FILE, encoding="utf-8") as f:
            existing = f.read()
        if existing != output:
            print(f"GEN-CHECK-001: {OUT_FILE} is out of date; re-run gen-annex29-columns.py", file=sys.stderr)
            sys.exit(1)
        print(f"GEN-ANNEX29 OK (check passed, {len(rows)} columns)")
    else:
        os.makedirs(os.path.dirname(OUT_FILE), exist_ok=True)
        with open(OUT_FILE, "w", encoding="utf-8") as f:
            f.write(output)
        print(f"GEN-ANNEX29 OK: generated {OUT_FILE} ({len(rows)} columns)")


if __name__ == "__main__":
    main()
